-- Share tokens are generated by a trigger that runs as the signed-in user,
-- who has no access to the private schema. Run the token helpers with the
-- owner's rights instead, with a pinned search path.

create or replace function private.new_share_token() returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  alphabet constant text := '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  bytes bytea := extensions.gen_random_bytes(10);
  result text := '';
begin
  for i in 0..9 loop
    result := result || substr(alphabet, (get_byte(bytes, i) % 62) + 1, 1);
  end loop;
  return result;
end $$;

create or replace function private.set_share_token() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.token := private.new_share_token();
  return new;
end $$;

create or replace function private.touch_updated_at() returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end $$;

revoke execute on all functions in schema private from public, anon, authenticated;
